import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
let activeId: string | undefined;

// A running row can only have belonged to a worker that has exited before this process starts.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, next_attempt_at=0 WHERE status='running'").run(new Date().toISOString());
const heartbeat = () => db.prepare('INSERT INTO worker_heartbeat(singleton,seen_at) VALUES(1,?) ON CONFLICT(singleton) DO UPDATE SET seen_at=excluded.seen_at').run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 750);
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

function claim(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND next_attempt_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as unknown as JobRow | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const changed = db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(new Date().toISOString(), row.id);
    db.exec('COMMIT');
    if (!changed.changes) return undefined;
    return db.prepare('SELECT * FROM jobs WHERE id=?').get(row.id) as unknown as JobRow;
  } catch (e) { try { db.exec('ROLLBACK'); } catch {} throw e; }
}

async function processJob(job: JobRow): Promise<void> {
  activeId = job.id;
  if (job.attempts <= job.fail_attempts) {
    // Simulated dependency failure happens before the first step.
    await sleep(20);
    if (stopping) {
      db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, next_attempt_at=0 WHERE id=? AND status='running'").run(new Date().toISOString(), job.id);
      activeId = undefined; return;
    }
    if (job.attempts >= 3) {
      db.prepare("UPDATE jobs SET status='failed', error='transient failure', result=NULL, updated_at=? WHERE id=? AND status='running'").run(new Date().toISOString(), job.id);
    } else {
      db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, next_attempt_at=? WHERE id=? AND status='running'").run(new Date().toISOString(), Date.now() + 500, job.id);
    }
    activeId = undefined; return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(100);
    if (stopping) {
      db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, next_attempt_at=0 WHERE id=? AND status='running'").run(new Date().toISOString(), job.id);
      activeId = undefined; return;
    }
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step, new Date().toISOString(), job.id);
  }
  db.prepare("UPDATE jobs SET status='completed', result=?, error=NULL, progress_completed=steps, updated_at=? WHERE id=? AND status='running'").run(job.input.toUpperCase(), new Date().toISOString(), job.id);
  activeId = undefined;
}

console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const job = claim();
    if (job) await processJob(job);
    else await sleep(100);
  }
} finally {
  if (activeId) db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, next_attempt_at=0 WHERE id=? AND status='running'").run(new Date().toISOString(), activeId);
  clearInterval(heartbeatTimer);
  db.close();
}

