13	  </style>
14	</head>
15	<body>
16	  <h1>Job tracker</h1>
17	  <form data-testid="job-form">
18	    <label>Input <input data-testid="job-input" name="input" required maxlength="1000"></label>
19	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
20	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
21	    <button data-testid="job-submit" type="submit">Submit job</button>
22	    <div data-testid="form-error" role="alert"></div>
23	  </form>
24	  <h2>Jobs</h2>
25	  <section data-testid="job-list" aria-live="polite"></section>
26	  <script>
27	    const form = document.querySelector('[data-testid="job-form"]');
28	    const alertRegion = document.querySelector('[data-testid="form-error"]');
29	    const list = document.querySelector('[data-testid="job-list"]');
30	    const input = document.querySelector('[data-testid="job-input"]');
31	    const steps = document.querySelector('[data-testid="job-steps"]');
32	    const failures = document.querySelector('[data-testid="job-fail-attempts"]');
33	    function fieldText(error) {
34	      const err = error?.error;
35	      if (!err) return 'Could not submit the job.';
36	      if (Array.isArray(err.fields) && err.fields.length) return `${err.message} ${err.fields.map(f => `${f.field}: ${f.message}`).join(' ')}`;
37	      return err.message || 'Could not submit the job.';
38	    }
39	    form.addEventListener('submit', async event => {
40	      event.preventDefault(); alertRegion.textContent = '';
41	      try {
42	        const response = await fetch('/api/jobs', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({input:input.value, steps:Number(steps.value), failAttempts:Number(failures.value)})});
43	        const data = await response.json();
44	        if (!response.ok) { alertRegion.textContent = fieldText(data); return; }
45	        input.value = '';
46	        await refresh();
47	      } catch { alertRegion.textContent = 'Could not reach the job server.'; }
48	    });
49	    async function refresh() {
50	      try {
51	        const response = await fetch('/api/jobs'); if (!response.ok) return;
52	        const {jobs} = await response.json();
53	        list.replaceChildren(...jobs.map(job => {
54	          const item = document.createElement('article'); item.className='job'; item.dataset.testid='job-item'; item.dataset.jobId=job.id;
55	          const title = document.createElement('strong'); title.textContent=job.input;
56	          const status = document.createElement('span'); status.dataset.testid='job-status'; status.textContent=job.status;
57	          const progress = document.createElement('span'); progress.dataset.testid='job-progress'; progress.textContent=`${job.progress.completed}/${job.progress.total}`;
58	          const result = document.createElement('div'); result.dataset.testid='job-result'; result.textContent=job.result?.output ?? job.error ?? '';
59	          const meta = document.createElement('div'); meta.className='meta'; meta.append('Status: ',status,' · Progress: ',progress);
60	          item.append(title,meta,result); return item;
61	        }));
62	      } catch { /* A later poll will refresh the list when the server returns. */ }
63	    }
64	    refresh(); setInterval(refresh, 500);
65	  </script>
66	</body>
67	</html>
